#!/usr/bin/env node
// design/tokens.json → design/web/tokens.css (CSS variables) + Sources/NachoComboCore/Pet/PetDesignTokens.swift.
// One source, two outputs with the same values; PetDesignTokenTests checks all three agree.
// usage: node scripts/gen-design-tokens.mjs [--check]   (--check: exit 1 when a generated file is out of date)
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const src = path.join(root, 'design/tokens.json');
const cssOut = path.join(root, 'design/web/tokens.css');
const swiftOut = path.join(root, 'Sources/NachoComboCore/Pet/PetDesignTokens.swift');
const t = JSON.parse(fs.readFileSync(src, 'utf8'));

const kebab = (s) => s.replace(/([a-z0-9])([A-Z])/g, '$1-$2').toLowerCase();
const cap = (s) => s[0].toUpperCase() + s.slice(1);
const unitless = new Set(['font.weightRegular', 'font.weightMedium', 'font.weightSemibold', 'font.lineHeight', 'shadow.petOpacity']);
const cssValue = (group, key, v) => {
  if (typeof v === 'string') return v;
  if (unitless.has(`${group}.${key}`)) return String(v);
  return group === 'motion' ? `${v}ms` : `${v}px`;
};
const groups = ['size', 'space', 'radius', 'font', 'shadow', 'motion'];
const themes = ['light', 'dark'];
const colorKeys = Object.keys(t.color.light);
for (const th of themes) {
  const keys = Object.keys(t.color[th]);
  if (keys.join() !== colorKeys.join()) throw new Error(`color.${th} must have the same keys in the same order as color.light`);
  for (const k of keys) if (!/^#[0-9A-F]{6}([0-9A-F]{2})?$/.test(t.color[th][k])) throw new Error(`color.${th}.${k}: use #RRGGBB or #RRGGBBAA (upper case)`);
}
for (const g of groups) for (const [k, v] of Object.entries(t[g])) {
  if (!(typeof v === 'number' && Number.isFinite(v)) && !(g === 'font' && k === 'family')) throw new Error(`${g}.${k} must be a number`);
}

// ---- CSS ----
let css = '/* Generated by scripts/gen-design-tokens.mjs from design/tokens.json. Do not edit. */\n:root {\n';
for (const g of groups) for (const [k, v] of Object.entries(t[g])) css += `  --${g}-${kebab(k)}: ${cssValue(g, k, v)};\n`;
css += '}\n';
for (const th of themes) {
  css += th === 'light' ? ':root, [data-theme="light"] {\n' : '[data-theme="dark"] {\n';
  for (const k of colorKeys) css += `  --color-${kebab(k)}: ${t.color[th][k]};\n`;
  css += '}\n';
}

// ---- Swift ----
const num = (v) => (Number.isInteger(v) ? `${v}` : `${v}`);
let sw = `// Generated by scripts/gen-design-tokens.mjs from design/tokens.json. Do not edit.
// Points (= CSS px at 1x), milliseconds, colors as "#RRGGBB" / "#RRGGBBAA". The web mockup (design/web) reads the
// same values from design/web/tokens.css; PetDesignTokenTests checks the three files agree.

public enum PetTokens {
`;
for (const g of groups) {
  sw += `    public enum ${cap(g)} {\n`;
  for (const [k, v] of Object.entries(t[g])) {
    sw += typeof v === 'string' ? `        public static let ${k} = ${JSON.stringify(v)}\n` : `        public static let ${k}: Double = ${num(v)}\n`;
  }
  sw += '    }\n\n';
}
sw += '    public struct Palette: Equatable {\n';
for (const k of colorKeys) sw += `        public let ${k}: String\n`;
sw += '    }\n\n';
for (const th of themes) {
  sw += `    public static let ${th} = Palette(\n`;
  sw += colorKeys.map((k) => `        ${k}: "${t.color[th][k]}"`).join(',\n') + ')\n\n';
}
sw += '    /// Every token as "group.key" (colors "color.<theme>.key") → its value as written in tokens.json, built from the\n';
sw += '    /// constants above (so a hand edit of a constant shows up as a mismatch).\n';
sw += '    public static let flat: [String: String] = {\n        var d: [String: String] = [:]\n';
for (const g of groups) for (const [k, v] of Object.entries(t[g])) {
  sw += typeof v === 'string' ? `        d["${g}.${k}"] = ${cap(g)}.${k}\n` : `        d["${g}.${k}"] = text(${cap(g)}.${k})\n`;
}
for (const th of themes) for (const k of colorKeys) sw += `        d["color.${th}.${k}"] = ${th}.${k}\n`;
sw += `        return d
    }()

    /// 112 → "112", 1.4 → "1.4" (the way tokens.json writes numbers).
    public static func text(_ v: Double) -> String {
        v.rounded() == v && abs(v) < 1e15 ? String(Int(v)) : String(v)
    }
}
`;

const outputs = [[cssOut, css], [swiftOut, sw]];
if (process.argv.includes('--check')) {
  let stale = 0;
  for (const [f, body] of outputs) {
    const cur = fs.existsSync(f) ? fs.readFileSync(f, 'utf8') : '';
    if (cur !== body) { console.error(`out of date: ${path.relative(root, f)} (run node scripts/gen-design-tokens.mjs)`); stale = 1; }
  }
  if (!stale) console.log('design tokens: generated files are up to date');
  process.exit(stale);
}
for (const [f, body] of outputs) {
  fs.mkdirSync(path.dirname(f), { recursive: true });
  fs.writeFileSync(f, body);
  console.log(`wrote ${path.relative(root, f)}`);
}
